WITH reference AS (SELECT * FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW)=20 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma20,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW)=60 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma60,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 119 PRECEDING AND CURRENT ROW)=120 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 119 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma120,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma250 FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate<='2026-04-10') w WHERE bizdate='2026-04-10'), feature AS(SELECT f.* FROM dsl_rolling_diag_c26c5c6a0208.rolling_averages_v1 f WHERE f.bizdate='2026-04-10' AND f.snapshot_id='stock-20060104-20260414-v1' AND f.manifest_sha256='306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95' AND f.registry_fingerprint='a460a741b13b2cea6066c7a973c246463d68c6eb083c07a50650ed8403f3ab17') SELECT COUNT(*) FROM reference w FULL OUTER JOIN feature f ON w.mktcode=f.mktcode AND w.tgtcode=f.tgtcode WHERE w.mktcode IS NULL OR f.mktcode IS NULL OR ((f.ma20 IS NULL)!=(w.ma20 IS NULL)) OR ABS(f.ma20-w.ma20)>1e-10*GREATEST(1,ABS(w.ma20)) OR ((f.ma60 IS NULL)!=(w.ma60 IS NULL)) OR ABS(f.ma60-w.ma60)>1e-10*GREATEST(1,ABS(w.ma60)) OR ((f.ma120 IS NULL)!=(w.ma120 IS NULL)) OR ABS(f.ma120-w.ma120)>1e-10*GREATEST(1,ABS(w.ma120)) OR ((f.ma250 IS NULL)!=(w.ma250 IS NULL)) OR ABS(f.ma250-w.ma250)>1e-10*GREATEST(1,ABS(w.ma250));
